'use client';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { calendarDays, dateInZone, moveCalendar, type AgendaView } from '@/lib/agendaCalendar';
export default function AgendaCalendarToolbar({ view, date, timezone, onView, onDate, loading }: { view: AgendaView; date: string; timezone: string; onView: (view: AgendaView) => void; onDate: (date: string) => void; loading: boolean }) {
  const days = calendarDays(view, date);
  const label = (day: string, options: Intl.DateTimeFormatOptions) => new Intl.DateTimeFormat('es-MX', { ...options, timeZone: 'UTC' }).format(new Date(`${day}T12:00:00Z`));
  const title = view === 'reservations' ? 'Reservaciones del negocio' : view === 'month' ? label(date, { month: 'long', year: 'numeric' }) : view === 'week' ? `${label(days[0], { day: 'numeric', month: 'short' })} — ${label(days[6], { day: 'numeric', month: 'short', year: 'numeric' })}` : label(date, { dateStyle: 'long' });
  return <section className="space-y-4 rounded-3xl border border-gray-100 bg-white p-4 shadow-sm sm:p-5" aria-label="Navegación de Agenda" aria-busy={loading}>
    <div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-[#168e00]">Mi agenda</p><h2 className="mt-1 font-[family-name:var(--font-varela-round)] text-xl capitalize text-[#004e28]">{title}</h2></div>
      {view !== "reservations" ? <div className="flex flex-wrap items-center gap-2"><button type="button" aria-label="Período anterior" onClick={() => onDate(moveCalendar(view, date, -1))} className="flex size-11 items-center justify-center rounded-xl border border-gray-200 text-[#004e28]"><ChevronLeft size={18} /></button><button type="button" onClick={() => onDate(dateInZone(new Date(), timezone))} className="min-h-11 rounded-xl border border-gray-200 px-4 text-sm font-semibold text-[#004e28]">Hoy</button><button type="button" aria-label="Período siguiente" onClick={() => onDate(moveCalendar(view, date, 1))} className="flex size-11 items-center justify-center rounded-xl border border-gray-200 text-[#004e28]"><ChevronRight size={18} /></button><label><span className="sr-only">Seleccionar fecha de Agenda</span><input type="date" value={date} onChange={e => { if (e.target.value) onDate(e.target.value); }} className="h-11 max-w-40 rounded-xl border border-gray-200 px-2 text-sm text-[#004e28]" /></label></div> : null}
    </div>
    <div className="grid grid-cols-4 gap-1 rounded-2xl bg-[#f2f3f4] p-1" role="group" aria-label="Vista de Agenda">{([['day', 'Día'], ['week', 'Semana'], ['month', 'Mes'], ['reservations', 'Reservaciones']] as const).map(([value, label]) => <button key={value} type="button" aria-pressed={view === value} onClick={() => onView(value)} className={`min-h-11 rounded-xl px-1 text-xs font-semibold transition sm:px-4 sm:text-sm ${view === value ? 'bg-[#004e28] text-white shadow-sm' : 'text-gray-600 hover:bg-white'}`}>{label}</button>)}</div>
  </section>;
}
